/* PPC explainer: the glossary. Every term used across the pages, with the page that explains it.
   Hand-written (not generated). def: one plain sentence for the pop-up, no jargon inside it.
   more: a short paragraph with an example from the project, shown on the glossary page. */
window.GLOSSARY = [
  // --- the computer ------------------------------------------------
  {"id": "process", "term": "Process", "page": "machines", "def": "One running copy of a program, with memory of its own that no other program can see.", "more": "Start a program twice and you get two processes; what one keeps in memory the other cannot read. Every measurement in this study is of one fresh process: the native binary started again, or a browser started again with an empty profile (ADR 0005)."},
  {"id": "thread", "term": "Thread", "page": "machines", "def": "One line of work inside a process; all the threads of a process share its memory.", "more": "Eight threads can blur eight strips of the same image at once, because they all see the image. Two threads adding to the same counter must take turns, which is what RQ2 measures. N in this study is the number of threads, 1 to 8."},
  {"id": "core", "term": "Core", "page": "machines", "def": "The part of the chip that executes one thread at a time.", "more": "The PC used here has 8 fast cores set aside for the measurement (CPUs 0, 2, 4, ..., 14) and the study never runs more measured threads than that, so no thread waits for a core (ADR 0001)."},
  {"id": "p-core", "term": "P-core", "page": "machines", "def": "A performance core: one of the 8 fast cores of this chip, the only ones measured.", "more": "The i9-14900KF has 8 P-cores and 16 E-cores. Every run is confined to the P-cores with a CPU mask, and with SMT off each P-core is one CPU: 0, 2, 4, 6, 8, 10, 12, 14 (ADRs 0001, 0025, 0045)."},
  {"id": "e-core", "term": "E-core", "page": "machines", "def": "An efficiency core: slower than a P-core, and here used only for everything that is not the measurement.", "more": "CPUs 16 to 31 are E-cores. The harness, the results server and the rest of the system are pushed onto them by the shield, so they never compete with a run. The hybrid extra adds them to the measured set on purpose, to see what work stealing does with unequal cores (ADR 0059)."},
  {"id": "smt-hyperthreading", "term": "SMT (hyperthreading)", "page": "machines", "def": "A trick that lets one core run two threads at the same time, each slower than it would be alone.", "more": "With SMT on, 8 threads could land on 4 cores pretending to be 8, and a thread's speed would depend on its neighbour. It is turned off for every measurement, so N threads use N whole cores (ADR 0025)."},
  {"id": "turbo-boost", "term": "Turbo boost", "page": "machines", "def": "The chip running faster than its base speed while it is cool enough, and slowing again when it heats up.", "more": "The same program would take different times depending on temperature and on how many cores are busy. Turbo is off for every measurement, so the clock stays at the base 3.2 GHz whatever N is (ADR 0002)."},
  {"id": "base-clock", "term": "Base clock", "page": "machine", "def": "The speed the chip runs at when turbo is off.", "more": "3.2 GHz for these P-cores, requested by the governor and the same for every run. Cycle counts in the perf-v3 campaign are converted to time with it (ADR 0072)."},
  {"id": "governor", "term": "Governor", "page": "machine", "def": "The Linux rule that decides how fast the chip should run at each moment.", "more": "The performance governor holds the clock at the top allowed speed instead of dropping it to save power in the middle of a run; checked on every run (ADR 0002)."},
  {"id": "degraded-core", "term": "Degraded core", "page": "machine", "def": "One core of this PC that fails when pushed to high speeds.", "more": "It is CPU 12 of the measured mask. With the desktop's usual settings (turbo on) a test pinned to it crashed in 17 of 18 tries; with turbo off, the setting of every measurement, it passed 30 of 30, gave the right checksum and timed the filter as fast as the other cores. So it stays in the mask, and the measured build is made twice on the prepared PC (ADR 0085)."},
  {"id": "i9-14900kf", "term": "i9-14900KF", "page": "machine", "def": "The chip of the measuring PC: 8 fast cores and 16 slower ones.", "more": "An Intel Raptor Lake chip; its P-cores are the Raptor Cove design. Everything in the study was measured on this one chip (ADR 0001)."},
  {"id": "itmt", "term": "ITMT", "page": "machine", "def": "A Linux rule that prefers to put work on the fastest cores, which are exactly the ones being measured.", "more": "Intel Turbo Boost Max Technology scheduling. Left alone, it would push the harness and the desktop onto the P-cores during a run; the shield exists to stop that (ADR 0028)."},
  {"id": "cache", "term": "Cache", "page": "memory", "def": "A small, fast memory next to a core that keeps copies of the data the core is using.", "more": "Fetching from main memory takes on the order of a hundred clock steps; from the core's own first-level cache, about one. L1 and L2 belong to one core, L3 is shared by all of them."},
  {"id": "l1d-l3", "term": "L1D, L3", "page": "memory", "def": "The first-level data cache of one core, and the last-level cache shared by all cores.", "more": "The filter's two 64 MiB images do not fit in this chip's 36 MB L3, so the filter streams from main memory, and about half of its lost efficiency at N = 8 is the cores waiting for it (ADR 0091)."},
  {"id": "cache-line", "term": "Cache line", "page": "memory", "def": "The block of 64 bytes that memory and caches exchange; data never moves one byte at a time.", "more": "A counter is 8 bytes, so 8 of them fit in one line. The study gives every shared counter a line of its own by padding it to 128 bytes (ADR 0008)."},
  {"id": "line-move", "term": "Line move", "page": "rq2", "def": "A cache line travelling from one core to another because the second core needs data the first one changed.", "more": "Each move costs on the order of a hundred nanoseconds on this kind of CPU, against about one for data already in the core's own cache. The CPU counts them as HITMs; the atomic histogram at k = 1 is bounded by them, not by the arithmetic (ADR 0072)."},
  {"id": "memory-bandwidth", "term": "Memory bandwidth", "page": "extras", "def": "How many bytes per second all the cores together can read from main memory.", "more": "A shared resource: 8 cores reading at once get less each. The native filter at N = 8 reads 20.6 GB/s and writes as much; the faster one thread goes through memory, the less eight threads gain (ADR 0091)."},
  {"id": "adjacent-line-prefetcher", "term": "Adjacent-line prefetcher", "page": "memory", "def": "A part of Intel chips that fetches cache lines two at a time, the one asked for and its neighbour.", "more": "Because of it, two counters 64 bytes apart can still get in each other's way. That is why the counters are padded to 128 bytes, not 64 (ADR 0008; the pad64 pilot in ADR 0049 found at most about 1 % of difference)."},
  {"id": "simd", "term": "SIMD", "page": "environments", "def": "One instruction that works on several values at once.", "more": "Here 128 bits at a time: 16 bytes, or 8 values of 16 bits. The filter uses it on both sides, SSE2 natively and simd128 in WASM, and the SIMD extra shows the filter is 3.9 to 4.9 times slower without it (ADR 0004, ADR 0091)."},
  {"id": "sse2", "term": "SSE2", "page": "environments", "def": "The 128-bit SIMD instructions that every x86-64 chip has.", "more": "The native build uses only these, no newer ones, so that native and WASM have the same SIMD width (ADR 0004)."},
  {"id": "avx2", "term": "AVX2", "page": "extras", "def": "Newer 256-bit SIMD instructions that this chip has and WASM does not.", "more": "Used only in the AVX2 extra, built with target-cpu=native on purpose to break the same-flags rule and see what native alone could gain (ADR 0057)."},
  {"id": "hardware-counters", "term": "Hardware counters", "page": "rq2", "def": "Counters inside the chip that count events as they happen: clock cycles, instructions, cache lines fetched from another core.", "more": "Read with perf stat. The perf-v3 campaign counted them on the 8 P-cores during 30 runs per cell and divided by the atomic adds, which is how the retries of Chrome's add were counted; two more campaigns isolate the counters of the loop alone (ADR 0072, ADR 0090)."},
  {"id": "hitm", "term": "HITM", "page": "rq2", "def": "A count of the times a core needed a cache line that another core had just changed, so the line had to travel between them.", "more": "Short for hit modified. The perf-v3 campaign counts HITMs per atomic add: natively at k = 256 about one per add, in Chrome the line is also read before it is written (data/tables/perf-v3/perf-v3-counters.csv)."},
  {"id": "rfo", "term": "RFO", "page": "rq2", "def": "A core asking for a cache line because it wants to write into it, not only read it.", "more": "Short for read for ownership. Every atomic add needs one when the line is elsewhere; counted as ocr.demand_rfo.l3_hit.snoop_hitm in the perf-v3 campaign (ADR 0072)."},
  {"id": "perf-perf-stat-perf-c2c", "term": "perf, perf stat, perf c2c", "page": "rq2", "def": "The Linux tool that reads the chip's counters: stat counts events, c2c finds which cache lines cores fight over.", "more": "perf stat counted the P-cores in 100 ms intervals during the perf-v3 campaign; perf c2c showed, on the earlier build, that each padded counter sits alone on its line in WASM memory too (ADR 0072; those reports are at the tag data/v2)."},
  {"id": "uop", "term": "uop", "page": "atomics", "def": "One of the small internal steps a chip splits an instruction into.", "more": "Short for micro-operation. An add with a memory operand is split into a load, an add and a store; the k = 1 instruction-choice story in ADR 0060 is about such a split."},
  {"id": "dependency-chain", "term": "Dependency chain", "page": "atomics", "def": "A sequence of instructions where each one needs the result of the previous one, so the chip cannot overlap them.", "more": "With k = 1 every pixel adds to the same counter, so each add waits for the one before it. That is why the k = 1 local histogram is slow even with no atomics at all (ADR 0060)."},
  {"id": "store-buffer-store-to-load-forwarding", "term": "Store buffer, store-to-load forwarding", "page": "atomics", "def": "A core keeps values it just wrote in a small buffer and can hand one straight to the next read of the same place, without going to the cache.", "more": "The k = 1 loop reads the counter it has just written, every pixel, so its speed is the forwarding delay: about 7.4 cycles per pixel natively (ADR 0060)."},
  {"id": "locked-read-modify-write", "term": "Locked read-modify-write", "page": "atomics", "def": "An x86 instruction that reads a value, changes it and writes it back as one step no other core can get in the middle of.", "more": "Written with a lock prefix: lock add, lock inc, lock xadd, lock cmpxchg. It is how an atomic add is done natively and in Firefox; it also acts as a full memory barrier."},
  {"id": "compare-and-swap", "term": "Compare-and-swap", "page": "rq2", "def": "An instruction that writes a new value only if memory still holds the value the core read earlier; if not, it fails and the program usually tries again.", "more": "Chrome's optimizing compiler adds to a shared counter this way: read, compute, compare-and-swap, retry on failure. On a counter that eight threads hit, about one add in four retries. Native code and Firefox use a single locked add instead, which cannot fail. A native program made to add this way gets Chrome's times (ADR 0089)."},
  // --- concurrency -------------------------------------------------
  {"id": "atomic-operation", "term": "Atomic operation", "page": "atomics", "def": "A change to memory that happens in one indivisible step, so no other thread can see it half done or get in between.", "more": "fetch_add in Rust, Atomics.add in JavaScript. The atomic histogram adds 1 to a shared counter this way for every pixel; without it, two threads could both read 41 and both write 42, losing one count."},
  {"id": "memory-ordering-relaxed-seqcst", "term": "Memory ordering (Relaxed, SeqCst)", "page": "atomics", "def": "A setting on an atomic operation that says how much other memory traffic may be reordered around it.", "more": "It makes no difference here: WASM atomics are always the strictest kind, and on x86 a locked instruction is a full barrier whatever you ask for. So the study's RQ2 effect is not about ordering (CLAUDE.md, Technical notes)."},
  {"id": "data-race", "term": "Data race", "page": "rust", "def": "Two threads touching the same memory at the same time, at least one of them writing, with nothing to keep them apart.", "more": "The result is unpredictable. Rust's borrowing rules refuse such code at compile time, which is why the filter and the local histogram cannot have one, and the atomic histogram uses atomics to share safely."},
  {"id": "fork-join", "term": "Fork-join", "page": "threads", "def": "Splitting a job among several threads, then waiting until all of them are done.", "more": "Every Rayon parallel call is one fork-join. Its fixed cost is measured in every run by timing an empty broadcast: about 7.9 µs natively and 110 µs in Chrome at N = 8, medians over runs (data/tables/campaign-v3/campaign-v3-fork-join.csv)."},
  {"id": "thread-pool", "term": "Thread pool", "page": "threads", "def": "A set of threads created once and reused for every parallel job, instead of starting new ones each time.", "more": "Rayon keeps a pool of N workers; starting it is slow (new OS threads, or new Web Workers), so the study starts it before the clock and measures only the work (ADR 0005)."},
  {"id": "rayon", "term": "Rayon", "page": "threads", "def": "The Rust library that runs loops on several threads for you.", "more": "par_iter turns a loop over rows into parallel work; broadcast runs a closure on every worker. The same Rayon code runs natively and, through wasm-bindgen-rayon, in the browser."},
  {"id": "work-stealing", "term": "Work stealing", "page": "threads", "def": "When a thread runs out of work, it takes half of what another thread still has to do.", "more": "This is how Rayon keeps every core busy without planning the split in advance. In the hybrid extra it balances fast and slow cores on its own (ADR 0061)."},
  {"id": "futex", "term": "Futex", "page": "threads", "def": "The Linux mechanism a thread uses to go to sleep until another thread wakes it.", "more": "Short for fast user-space mutex. Natively, idle Rayon workers sleep on one; in the browser the same job is done by Atomics.wait and Atomics.notify."},
  {"id": "oversubscription", "term": "Oversubscription", "page": "threats", "def": "More threads wanting to run than there are cores to run them, so some wait their turn.", "more": "At N = 8 a browser's own threads and the coordinating worker share the 8 cores with the 8 workers. How much they take during a timed iteration was not established, so it is declared with the results (ADR 0080)."},
  {"id": "privatization", "term": "Privatization", "page": "workloads", "def": "Giving every task its own copy of a shared result, and adding the copies up at the end.", "more": "The local histogram does this: each task counts into its own 256-bin table over a 64 KiB chunk, and the tables are merged with fold and reduce. No thread ever writes to another's counters (ADR 0013)."},
  {"id": "true-sharing", "term": "True sharing", "page": "memory", "def": "Several threads really writing to the same variable.", "more": "The atomic histogram at small k: with k = 1 all eight threads add to one counter, and the cache line that holds it moves from core to core for every add."},
  {"id": "false-sharing", "term": "False sharing", "page": "memory", "def": "Threads writing to different variables that happen to sit in the same cache line, and still slowing each other down as if they shared one.", "more": "The packed extra puts 8 counters in one line on purpose: at k = 256 it makes the atomic histogram 1.18 times slower natively and 3.45 times slower in Chrome (ADR 0054)."},
  {"id": "contention", "term": "Contention", "page": "memory", "def": "Several cores wanting to write the same cache line at the same time, so they have to take turns.", "more": "The histogram's input sets how much of it there is: k = 1 sends every add to one line, k = 256 spreads the adds over 256 lines (ADR 0026)."},
  {"id": "pad64", "term": "pad64", "page": "memory", "def": "A build switch that pads each counter to 64 bytes instead of 128.", "more": "Used only in a pilot that compared the two paddings natively and found at most about 1 % of difference, so 128 was kept as the safer choice and the switch was removed from the code (ADR 0049, ADR 0075)."},
  // --- the browser and webassembly ---------------------------------
  {"id": "compiler", "term": "Compiler", "page": "compilers", "def": "The program that turns source code a person wrote into machine code a chip can run.", "more": "The Rust compiler makes both the native binary and the .wasm file from the same source. The browser's engine then compiles the .wasm a second time, into machine code for this chip, and that second step is part of what the study measures."},
  {"id": "machine-code", "term": "Machine code", "page": "compilers", "def": "The numbers a chip actually executes, each one a small step such as add these two or store that.", "more": "Each chip family has its own set; this PC's is x86-64. The study captured the machine code each engine runs for each kernel, V8's from its own dumps and Firefox's out of the browser's memory (data/probes/engine-code)."},
  {"id": "engine", "term": "Engine", "page": "compilers", "def": "The part of a browser that runs JavaScript and WebAssembly, by turning them into machine code.", "more": "V8 in Chrome, SpiderMonkey in Firefox. For the same .wasm each makes its own machine code, and for the atomic add they made different code, which is where RQ2's result comes from."},
  {"id": "jit-tier-up", "term": "JIT, tier-up", "page": "compilers", "def": "An engine first compiles code quickly so it can start, then recompiles the parts that run a lot with a slower, better compiler.", "more": "JIT means just in time. Until the better code is in place a program runs slower, which is why every run begins with warm-up iterations that are recorded but not analysed (ADR 0043)."},
  {"id": "llvm", "term": "LLVM", "page": "compilers", "def": "The compiler back end that the Rust compiler uses to produce machine code for both targets.", "more": "It emits the native lock inc for the atomic add and the SSE2 code for the filter; the k = 1 instruction-choice story in ADR 0060 is about one of its choices."},
  {"id": "v8", "term": "V8", "page": "environments", "def": "Chrome's engine for JavaScript and WebAssembly.", "more": "It has two WebAssembly compilers, a baseline one and an optimizing one (TurboFan). For the atomic add the optimizing one emits a load and a compare-and-swap loop, the baseline one a single lock xadd (data/probes/engine-code, ADR 0089)."},
  {"id": "turbofan", "term": "TurboFan", "page": "environments", "def": "The slower, better compiler inside V8 that recompiles code that runs a lot.", "more": "Its code for the k = 1 local loop is a plain load, add and store sequence, which is what ADR 0060 compares with the native code."},
  {"id": "spidermonkey", "term": "SpiderMonkey", "page": "environments", "def": "Firefox's engine for JavaScript and WebAssembly.", "more": "Its optimizing tier is called Ion. For the atomic add it emits one locked add per pixel, like native code, which is why Firefox is never worse than native in RQ2 (data/probes/engine-code)."},
  {"id": "chrome-for-testing", "term": "Chrome for Testing", "page": "environments", "def": "A version of Chrome that Google publishes for automated tests and that never updates itself.", "more": "Version 155.0.8059.84 is pinned here. A pilot showed it gives the same numbers as the ordinary Chrome of the same version, within 1.3 % (ADR 0021, ADR 0050)."},
  {"id": "headless", "term": "Headless", "page": "environments", "def": "Running a browser without opening a window.", "more": "Both browsers run headless during a campaign. A pilot compared it with windows open and found at most 0.3 % of difference at N = 8 (ADR 0046)."},
  {"id": "fresh-profile", "term": "Fresh profile", "page": "environments", "def": "A new, empty set of browser settings and caches for every run, thrown away afterwards.", "more": "So nothing from one run (a cached module, a setting, an update) can leak into the next. The launcher creates a temporary profile directory per run (ADR 0022)."},
  {"id": "web-worker", "term": "Web Worker", "page": "threads", "def": "A JavaScript thread that runs beside the page, with its own memory, talking to the page by messages.", "more": "With WASM threads, each Rayon worker lives in one Web Worker, and all of them share the module's memory through a SharedArrayBuffer."},
  {"id": "coordinator-worker", "term": "Coordinator worker", "page": "environments", "def": "The one Web Worker that starts the run and is allowed to wait for the others.", "more": "The page's main thread may never block, so it cannot call run(); this worker does, waits while the pool works, and posts the results back (ADR 0020)."},
  {"id": "sharedarraybuffer", "term": "SharedArrayBuffer", "page": "environments", "def": "A block of memory that several Web Workers can read and write at the same time.", "more": "The WASM module's memory is one, which is what lets eight workers blur the same image. Browsers only allow it on a cross-origin isolated page."},
  {"id": "linear-memory", "term": "Linear memory", "page": "environments", "def": "The single flat block of bytes a WASM module owns; all its data lives there.", "more": "With threads it is a SharedArrayBuffer seen by every worker. perf c2c showed that the padded counters keep their 128-byte spacing inside it (ADR 0072)."},
  {"id": "atomics-wait-atomics-notify", "term": "Atomics.wait / Atomics.notify", "page": "environments", "def": "JavaScript calls that let a worker go to sleep on a shared memory location, and wake it again.", "more": "They are the browser's version of a futex. The page's main thread is not allowed to call wait, which is why a coordinating worker exists."},
  {"id": "cross-origin-isolation", "term": "Cross-origin isolation", "page": "environments", "def": "A state a web page can be in that unlocks shared memory between workers.", "more": "The page checks crossOriginIsolated === true before starting and fails early with a clear message if the server did not send the headers that grant it."},
  {"id": "coop-coep-corp", "term": "COOP / COEP / CORP", "page": "environments", "def": "Three answers a web server sends with a page that together put it in the isolated state shared memory needs.", "more": "Cross-Origin-Opener-Policy: same-origin, Cross-Origin-Embedder-Policy: require-corp, Cross-Origin-Resource-Policy: same-origin, sent by harness/server.py (ADR 0019)."},
  {"id": "bounds-checking", "term": "Bounds checking", "page": "environments", "def": "A check, on every memory access of a WASM program, that the address is inside the program's memory.", "more": "Native code has no such check. It is one of the reasons the literature gives for WASM's constant factor; the study counted the result, a third more instructions per pixel in the filter, not the checks themselves (ADR 0091)."},
  {"id": "performance-now", "term": "performance.now()", "page": "protocol", "def": "The browser's clock for measuring time inside a page.", "more": "It is made coarse on purpose, to make timing attacks harder: 5 µs steps in Chrome and 20 µs in Firefox here. Every configuration takes at least 100 times that, so the coarseness does not matter (ADR 0041)."},
  {"id": "simd128", "term": "simd128", "page": "environments", "def": "WebAssembly's 128-bit SIMD instructions.", "more": "The counterpart of SSE2 on the native side; both do 16 bytes at a time, so the filter is vectorized the same width in every environment (ADR 0004)."},
  {"id": "wasm32", "term": "wasm32", "page": "environments", "def": "The 32-bit WebAssembly target the Rust compiler builds for.", "more": "wasm32-unknown-unknown: addresses are 32 bits there, so a memory of at most 4 GiB, and usize is 32 bits."},
  {"id": "wasm-bindgen", "term": "wasm-bindgen", "page": "environments", "def": "The tool that writes the JavaScript glue between the Rust code and the page.", "more": "It produces pkg/bench.js next to the .wasm; its version is pinned at 0.2.129 so every build is the same (bench/Cargo.toml)."},
  {"id": "wasm-bindgen-rayon", "term": "wasm-bindgen-rayon", "page": "environments", "def": "The library that runs Rayon's thread pool on Web Workers that share the WASM memory.", "more": "It starts N workers, hands each the module and its memory, and makes them the pool, so the same par_iter code runs in the browser."},
  {"id": "jitdump-perf-prof", "term": "jitdump (--perf-prof)", "page": "environments", "def": "A V8 flag that writes every function the engine compiles to a file, so its machine code can be read.", "more": "Written to jit-<pid>.dump and read with analysis.extras.jitdump; Firefox 158 has no equivalent, so its code was read from the process memory instead (scripts/capture_firefox.py)."},
  // --- rust and the build ------------------------------------------
  {"id": "nightly-toolchain", "term": "Nightly toolchain", "page": "rust", "def": "A pre-release version of the Rust compiler, with features the stable one does not have yet.", "more": "Pinned to nightly-2026-10-03 in bench/rust-toolchain.toml, because WASM threads need -Z build-std, which only nightly offers (ADR 0009)."},
  {"id": "z-build-std", "term": "-Z build-std", "page": "rust", "def": "A flag that rebuilds Rust's standard library from source as part of the build.", "more": "Needed because the prebuilt WASM standard library is compiled without atomics; the rebuild turns them on (ADR 0009)."},
  {"id": "atomics-bulk-memory-mutable-globals", "term": "+atomics, +bulk-memory, +mutable-globals", "page": "rust", "def": "Three WebAssembly features the build turns on: shared memory with atomics, fast memory copying, and a per-thread stack pointer.", "more": "Without all three a WASM module cannot run threads at all. They are set in bench/.cargo/config.toml together with simd128."},
  {"id": "codegen-units-1-lto-fat", "term": "codegen-units = 1, lto = \"fat\"", "page": "rust", "def": "Build settings that compile the whole program as one piece and let the compiler optimize across all of it.", "more": "The same for the native and the WASM build, so neither side gets an optimization the other does not (bench/Cargo.toml)."},
  {"id": "target-cpu-native", "term": "target-cpu=native", "page": "rust", "def": "A flag that lets the compiler use every instruction this exact chip has.", "more": "Off in the main campaign, so the native build uses only what every x86-64 chip has (SSE2). On only in the AVX2 extra, which exists to show what that costs (ADR 0057)."},
  {"id": "cargo-feature", "term": "Cargo feature", "page": "rust", "def": "A named switch chosen at build time that includes or excludes a piece of code.", "more": "The bench has none today. An earlier one, pad64, padded the counters to 64 bytes for a pilot and was removed afterwards (ADR 0075); the scalar and AVX2 builds are made with compiler flags, not features."},
  {"id": "codegen-neutral", "term": "Codegen-neutral", "page": "changing", "def": "A change to the source that leaves the machine code of every measured function exactly as it was.", "more": "Renaming a variable or splitting a function is usually neutral; changing a loop usually is not. scripts/codegen_diff.sh checks it, and a change that is not neutral makes a new build with a new tag (ADR 0062)."},
  {"id": "codegen-diff", "term": "Codegen diff", "page": "changing", "def": "The script that compares the machine code of two builds, function by function.", "more": "bash scripts/codegen_diff.sh builds the base commit and the working tree the same way and reports which functions differ; a changed hot function means a new build and a new tag (ADR 0062)."},
  // --- linux and the harness ---------------------------------------
  {"id": "make", "term": "make", "page": "setup", "def": "A tool that runs named recipes written in a Makefile.", "more": "make build, make test, make campaign: each name runs the commands under it in make/*.mk. make help lists the ones meant for you."},
  {"id": "make-target", "term": "make target", "page": "workflow", "def": "One named recipe in the Makefile.", "more": "make build runs the commands under build: in make/build.mk. Targets marked #: are helpers that make help hides."},
  {"id": "csv", "term": "CSV", "page": "setup", "def": "A plain-text table: one row per line, values separated by commas.", "more": "The native runner prints one CSV row per timed iteration; the browser page posts the same rows. data/raw/<campaign>/<run>.csv is one of these per run."},
  {"id": "orchestrator", "term": "Orchestrator", "page": "code", "def": "The Python program that starts every run of a campaign, one fresh process at a time, and records what it found.", "more": "python3 -m harness.campaign <spec>. It never measures anything itself: it starts the binary or the browser, waits, and writes the run's JSON next to its CSV (ADR 0034)."},
  {"id": "query-string", "term": "Query string", "page": "code", "def": "The part of a web address after the question mark: name=value pairs joined by &amp;.", "more": "The benchmark page reads its whole configuration from it (workload, threads, width, ...), the way the native program reads its command line (ADR 0018)."},
  {"id": "spec", "term": "Spec", "page": "campaigns", "def": "The JSON file that fixes every parameter of a campaign before it runs.", "more": "harness/campaigns/campaign-v3.json lists environments, workloads, thread counts, repetitions and the order seed. The harness copies it into campaign.json, and a resume refuses to continue if it changed (ADR 0034)."},
  {"id": "cpu-affinity-mask", "term": "CPU affinity mask", "page": "machine", "def": "The list of CPUs a process is allowed to run on.", "more": "Every run gets 0,2,4,6,8,10,12,14, the eight P-cores. It is set on the whole process, because a browser gives no way to pin single threads (ADR 0001)."},
  {"id": "taskset", "term": "taskset", "page": "machine", "def": "A Linux command that starts a program with a CPU affinity mask.", "more": "taskset -c 0,2,4,6,8,10,12,14 <command>. The launcher starts both the native binary and the browsers this way (ADR 0022)."},
  {"id": "sched-setaffinity", "term": "sched_setaffinity", "page": "machine", "def": "The system call a program uses to choose the CPUs it may run on.", "more": "The harness calls it on itself to move onto the E-cores, so it never competes with the run it is measuring."},
  {"id": "cgroup-cpuset", "term": "cgroup, cpuset", "page": "machine", "def": "A Linux way of grouping processes and limiting what the group may use; cpuset limits which CPUs.", "more": "The shield puts the rest of the system in groups limited to the E-cores, and each run in a group limited to the P-cores (ADR 0028)."},
  {"id": "systemd-scope-slice", "term": "systemd scope, slice", "page": "machine", "def": "A scope is a group of running processes that systemd manages as one unit; a slice is a container for such units.", "more": "Each run is a transient scope named ppc-run-<id> inside ppc-bench.slice, allowed only the P-cores. Any browser process found outside its scope fails the run (ADR 0028, ADR 0045)."},
  {"id": "systemd-run", "term": "systemd-run", "page": "machine", "def": "A command that starts a program inside a new systemd unit.", "more": "The harness uses it to start each run in its own scope; it is one of the two commands the sudoers rule allows without a password."},
  {"id": "systemd-inhibit", "term": "systemd-inhibit", "page": "machine", "def": "A command that stops the machine from going to sleep while another command runs.", "more": "Every campaign runs under it, so a two-hour campaign is not interrupted by the desktop's idle timer (ADR 0042)."},
  {"id": "shield", "term": "Shield", "page": "machine", "def": "Keeping everything that is not the measurement off the measured cores.", "more": "system.slice, user.slice and init.scope are limited to the E-cores before a session, so only the run itself touches the P-cores. make env-setup turns it on (ADR 0028)."},
  {"id": "quiet-mode", "term": "Quiet mode", "page": "machine", "def": "Closing and stopping everything on the PC that could do work in the background during a campaign.", "more": "make quiet stops the file indexer, automatic updates, docker and the desktop apps; make quiet-off starts them again (ADR 0070)."},
  {"id": "escaped-process", "term": "Escaped process", "page": "machine", "def": "A browser process that ended up outside the group that confines its run to the P-cores.", "more": "Chrome did this through the desktop message bus in a pilot. Strict validation now checks every browser process and fails the run if one escaped (ADR 0045)."},
  {"id": "session-bus-d-bus", "term": "Session bus (D-Bus)", "page": "machine", "def": "The channel desktop programs use to talk to each other on Linux.", "more": "Through it Chrome asked the desktop to start parts of itself outside the run's scope. The launcher withholds it from the browsers (ADR 0045)."},
  {"id": "foreign-cpu-time", "term": "Foreign CPU time", "page": "machine", "def": "Time the measured cores spent busy on something other than the run.", "more": "Read from /proc/stat and compared with the run's own CPU time. A run with more than 0.25 s of it is excluded by the data check (ADR 0051)."},
  {"id": "proc-stat", "term": "/proc/stat", "page": "machine", "def": "A file the Linux kernel keeps with how busy each CPU has been.", "more": "Its resolution is 10 ms. The harness reads it before and after a run to compute the foreign CPU time."},
  {"id": "getrusage", "term": "getrusage", "page": "machine", "def": "A system call that tells how much CPU time a process and its children used.", "more": "Used for native runs to know the run's own CPU time, which is subtracted from the busy time of the P-cores."},
  {"id": "kworker-irq", "term": "kworker, IRQ", "page": "machine", "def": "Work the Linux kernel itself does on a core: its own helper threads and the handling of hardware interrupts.", "more": "The shield cannot move them off the P-cores; the foreign CPU time measures how much of it there was (ADR 0028)."},
  {"id": "sudoers-rule", "term": "sudoers rule", "page": "setup", "def": "A line that lets a user run certain commands as the administrator without typing a password.", "more": "make sudoers allows systemd-run and systemctl only, so the harness can create run scopes. It is passwordless root for those two commands: keep it to the measuring PC and remove it after the campaigns (ADR 0028)."},
  {"id": "apparmor-profile", "term": "AppArmor profile", "page": "machine", "def": "An Ubuntu security rule that says what a program may do.", "more": "One is loaded for the pinned Chrome only, because Ubuntu otherwise blocks the user namespaces Chrome's sandbox needs (make chrome-apparmor)."},
  {"id": "user-namespaces", "term": "User namespaces", "page": "machine", "def": "A Linux feature a program uses to wall itself off from the rest of the system.", "more": "Chrome's sandbox needs it; Ubuntu restricts it for ordinary programs, hence the AppArmor profile."},
  // --- measuring and statistics ------------------------------------
  {"id": "noise", "term": "Noise", "page": "measuring", "def": "Run-to-run differences in time that are not the program's doing.", "more": "Other programs, cache contents, temperature, where the operating system put the threads. Repeating a run 30 times turns noise into a spread you can see and measure, instead of one number you cannot trust."},
  {"id": "bias", "term": "Bias", "page": "measuring", "def": "A difference that shows up every time, for a reason other than the one being compared.", "more": "A faster machine for one browser, or always running Chrome first. Repeating does not remove it; a fair design does: one machine, the same settings, and runs in a random interleaved order (ADR 0034)."},
  {"id": "sample", "term": "Sample", "page": "measuring", "def": "The measurements you have, as opposed to all the ones you could have taken.", "more": "30 runs are a sample. Another 30 would come out a little different, and the bootstrap interval says how different."},
  {"id": "mean", "term": "Mean", "page": "measuring", "def": "The usual average: add the values, divide by how many there are.", "more": "One very slow run pulls it up. The study uses the median inside a run and the geometric mean across runs instead, for reasons each has."},
  {"id": "median", "term": "Median", "page": "reading", "def": "The middle value when the values are sorted.", "more": "Each run's 10 timed iterations become one number this way, so one odd iteration cannot drag the run (analysis plan D1, ADR 0037)."},
  {"id": "geometric-mean", "term": "Geometric mean", "page": "reading", "def": "An average made for ratios: multiply the values and take the root, or average their logarithms.", "more": "A run twice as slow and a run twice as fast average to no change with it, and to a 25 % slowdown with the usual mean. The 30 run values of a configuration become one time this way (ADR 0037)."},
  {"id": "log-scale", "term": "Log scale", "page": "ratios", "def": "A scale where each step multiplies instead of adds.", "more": "0.5, 1, 2, 4 are equally spaced on it, so twice as fast and twice as slow are the same distance from 1. Every ratio in the study is computed on it, and the average on it is the geometric mean."},
  {"id": "interval", "term": "Interval", "page": "measuring", "def": "The range a summary would land in if you took another sample.", "more": "20 minutes, give or take 2. Two settings are called different only when the interval of their ratio does not include 1."},
  {"id": "confidence-interval-ci", "term": "Confidence interval (CI)", "page": "reading", "def": "A range around an estimate that, with the stated confidence, holds the true value.", "more": "The study's primary intervals are 99.5 % ones, and the widest are within about 2 % (RQ1) and 7 % (RQ2) of the estimate (data/tables/campaign-v3/campaign-v3-contrasts.csv)."},
  {"id": "bootstrap-percentile", "term": "Bootstrap (percentile)", "page": "reading", "def": "A way to get an interval by pretending the 30 runs are the whole world: draw 30 of them at random with replacement, recompute, repeat thousands of times.", "more": "10 000 resamples, seed 0x5EED; the middle 95 % of the recomputed values is the interval. No assumption that the times follow a bell curve (ADR 0037)."},
  {"id": "p-value-bootstrap", "term": "p-value (bootstrap)", "page": "reading", "def": "The share of resamples that land on the wrong side of no effect, doubled.", "more": "Floored at 0.0001 because 10 000 resamples cannot resolve less. It feeds the Holm correction over the 10 primary contrasts (ADR 0038)."},
  {"id": "primary-contrast", "term": "Primary contrast", "page": "reading", "def": "One of the 10 comparisons the study decided, before measuring, would answer its questions.", "more": "At N = 8: the filter's speedup ratio per browser (RQ1, 2) and the synchronization ratio per browser and k (RQ2, 8). Only these get a yes or no (ADR 0037)."},
  {"id": "exploratory", "term": "Exploratory", "page": "reading", "def": "A result that describes rather than decides: reported with a plain 95 % interval and no correction for how many things were looked at.", "more": "The tier, counters, SIMD, cutoff, grain, weak scaling, extras and hybrid campaigns are all exploratory. They show a pattern or support an explanation; they are not tests (ADR 0052, ADR 0088)."},
  {"id": "family-wise-error", "term": "Family-wise error", "page": "reading", "def": "The chance that at least one of several yes-or-no answers is a false alarm.", "more": "With 10 answers at 5 % each, about 40 % that one is wrong. The Holm correction brings the chance for the whole family back to 5 %."},
  {"id": "bonferroni", "term": "Bonferroni", "page": "reading", "def": "The simplest correction for several tests: divide the allowed error by the number of tests.", "more": "0.05 / 10 = 0.005, which is why the primary intervals are 99.5 % ones (ADR 0037)."},
  {"id": "holm", "term": "Holm", "page": "reading", "def": "A correction for several tests that is never stricter than it needs to be: sort the p-values, demand the most from the smallest.", "more": "Sort ascending, multiply the i-th by the number still to decide, keep the running maximum. It controls the family-wise error like Bonferroni but rejects more when the effects are real (ADR 0038)."},
  {"id": "effect-size", "term": "Effect size", "page": "reading", "def": "How big a difference is, not only whether it exists.", "more": "Here always a ratio: Chrome's synchronization cost at k = 1 is 2.26 times native's. A tiny difference can be certain and still not matter."},
  {"id": "run", "term": "Run", "page": "protocol", "def": "One fresh start of the program, with its own warm-up and its own timed iterations.", "more": "The unit of analysis: every statistic counts runs, never iterations, because iterations of one run share everything the program start decided (ADR 0005, ADR 0047)."},
  {"id": "iteration", "term": "Iteration", "page": "protocol", "def": "One timed execution of the workload inside a run.", "more": "10 measured per run, after the warm-up. They become one number, the median, before anything else is computed."},
  {"id": "warm-up-w", "term": "Warm-up W", "page": "protocol", "def": "Iterations at the start of a run that are recorded but not analysed, so the engine's compilation and the caches settle first.", "more": "W is set per workload from long pilot runs, as 1.5 times the largest warm-up seen and at least 5; the same W in every environment (ADR 0043)."},
  {"id": "pseudo-replication", "term": "Pseudo-replication", "page": "protocol", "def": "Counting measurements that are not independent as if they were, which makes a result look more certain than it is.", "more": "Treating the 300 iterations of 30 runs as 300 samples would do this; the study counts 30 (Georges et al. 2007, ADR 0005)."},
  {"id": "speedup-relative", "term": "Speedup (relative)", "page": "ratios", "def": "How many times faster N threads are than 1 thread of the same program in the same place.", "more": "T(1) / T(N), computed inside each environment. A speedup is always read next to the absolute time ratio browser / native, because a slow start inflates it (ADR 0039)."},
  {"id": "efficiency", "term": "Efficiency", "page": "ratios", "def": "Speedup divided by the number of threads: how much of each thread is actually gained.", "more": "1 would be perfect. The filter reaches 0.87 natively, 0.87 in Chrome and 0.92 in Firefox at N = 8 (data/tables/campaign-v3/campaign-v3-scaling.csv)."},
  {"id": "strong-scaling", "term": "Strong scaling", "page": "rq1", "def": "Keeping the problem the same size and adding threads.", "more": "The main campaign: the same 8192 x 8192 image for every N, speedup T(1)/T(N) (ADR 0003)."},
  {"id": "weak-scaling", "term": "Weak scaling", "page": "extras", "def": "Growing the problem with the number of threads, so each thread always has the same amount of work.", "more": "The weak extra uses 8192 x 1024N pixels; perfect would be a flat time. The filter keeps 0.85 to 0.92 of it at N = 8 (ADR 0092)."},
  {"id": "superlinear", "term": "Superlinear", "page": "extras", "def": "A speedup above the number of threads.", "more": "It usually means the single-thread baseline was slow, not that the threads did better than perfect. Firefox's local histogram at k = 256 is one case: its one-thread run pays for cache misses that its eight-thread run does not (ADR 0091)."},
  {"id": "excess-time", "term": "Excess time", "page": "extras", "def": "The time above perfect scaling: T(N) minus T(1)/N.", "more": "For the filter it grows natively with the code's speed (scalar, baseline, AVX2 builds), as it would if the cores shared memory bandwidth (ADR 0058)."},
  {"id": "karp-flatt", "term": "Karp-Flatt serial fraction", "page": "reading", "def": "A number computed from a speedup that says how much of the program would have to be serial to explain it.", "more": "e = (1/S - 1/N) / (1 - 1/N). At N = 8 the filter gives 0.021 natively; the timed region has no serial part, so e here is a cost of running in parallel, not a serial fraction."},
  {"id": "analysis-plan-pre-registration", "term": "Analysis plan (pre-registration)", "page": "reading", "def": "The statistics written down and fixed before any campaign data existed.", "more": "docs/adr/0037-analysis-plan.md, ADR 0037. Deciding the tests before seeing the data stops the data from choosing its own test."},
  {"id": "contrast", "term": "Contrast", "page": "reading", "def": "A difference of log times that the plan defines and tests.", "more": "RQ1: log speedup browser minus native. RQ2: the synchronization ratio browser minus native. ABS: log time browser minus native (exploratory)."},
  {"id": "interaction", "term": "Interaction", "page": "reading", "def": "A difference of differences.", "more": "RQ2's metric: (browser atomic minus browser local) minus (native atomic minus native local), on the log scale. The input and the plain WASM cost cancel out (ADR 0026)."},
  {"id": "r-delta-r", "term": "r, delta r", "page": "rq2", "def": "r is how much more the atomic histogram costs than the local one, on the log scale; delta r is r in the browser minus r natively.", "more": "exp(delta r) is the number the study reports: 2.26 for Chrome at k = 1, 0.42 at k = 256, about 1 for Firefox at k = 1 (data/tables/campaign-v3/campaign-v3-contrasts.csv)."},
  {"id": "abs", "term": "ABS", "page": "reading", "def": "The exploratory comparison of absolute times: browser over native at the same N.", "more": "Not a primary contrast. It is what shows that WASM costs a constant factor per thread, 1.17 to 1.36 for the filter."},
  {"id": "mann-whitney-u", "term": "Mann-Whitney U", "page": "reading", "def": "A test of whether one group of values tends to be larger than another, using only their order, not their size.", "more": "The robustness check of the 10 primary contrasts: it reaches the same decision as the bootstrap on all 10 (data/tables/campaign-v3/campaign-v3-robustness.csv)."},
  {"id": "cliff-s-delta", "term": "Cliff's delta", "page": "reading", "def": "How often a value from one group beats a value from the other, as a number from -1 to 1.", "more": "Share of pairs where B > A minus share where B < A. The effect size that goes with Mann-Whitney; six primary contrasts have complete separation, delta = 1 or -1."},
  {"id": "cv-coefficient-of-variation", "term": "CV (coefficient of variation)", "page": "reading", "def": "The spread of the values as a share of their average.", "more": "Standard deviation divided by the mean: run-to-run noise in percent, reported in the quality tables (data/tables/*/*-quality.md)."},
  {"id": "skewness", "term": "Skewness", "page": "reading", "def": "How lopsided a set of values is.", "more": "Run times are lopsided to the slow side: a few runs are much slower, none much faster. Logarithms make them much less so, one more reason for the geometric mean (data/tables/campaign-v3/campaign-v3-shape.csv)."},
  {"id": "sensitivity-check", "term": "Sensitivity check", "page": "reading", "def": "Redoing the analysis with another reasonable choice, to see whether the answer changes.", "more": "Mean instead of median per run, median instead of geometric mean per configuration, re-pairing the runs at random: the decisions hold (data/tables/campaign-v3/campaign-v3-robustness.csv)."},
  {"id": "spearman-s-rho", "term": "Spearman's rho", "page": "campaigns", "def": "A measure of whether values tend to go up or down along an order, from -1 to 1.", "more": "The data check computes it between a configuration's run values and their position in the campaign; a strong trend would mean the machine changed during the campaign."},
  {"id": "order-drift", "term": "Order drift", "page": "campaigns", "def": "Run values of one configuration getting steadily slower or faster through the campaign.", "more": "Flagged when Spearman's rho is above 0.5 in size. The random interleaved order turns drift into noise instead of bias; the flag only says to look (ADR 0051)."},
  {"id": "clock-factor", "term": "Clock factor", "page": "campaigns", "def": "How many times longer than the clock's smallest step a measurement is.", "more": "A configuration is flagged when its median run value is under 100 times the clock resolution, because then the coarse browser clock would shape the numbers (ADR 0041)."},
  // --- the study's own words ---------------------------------------
  {"id": "control", "term": "Control", "page": "questions", "def": "The version of a task with the thing under study taken out, so the two can be compared.", "more": "The local histogram has no shared counters; the atomic one has. Their ratio is the cost of synchronization, and RQ2 compares that ratio between browser and native (ADR 0026)."},
  {"id": "validity", "term": "Validity", "page": "validity", "def": "Whether a result means what it claims to mean.", "more": "Four kinds: internal (something else caused it), construct (we measured the wrong thing), external (it only holds here), conclusion (the numbers do not support it). See Four ways a study fools itself."},
  {"id": "k", "term": "k", "page": "workloads", "def": "The number of different grey values in the histogram's input, which sets how much the threads fight over counters.", "more": "k = 1: every pixel goes to one counter and eight threads queue on one cache line. k = 256: the adds spread over 256 counters. The study uses 1, 4, 16 and 256 (ADR 0026)."},
  {"id": "few-colors-k-noise", "term": "few_colors(k), noise", "page": "workloads", "def": "The two inputs: an image with k evenly spaced grey levels, and an image of random bytes.", "more": "few_colors(k) is the histogram's input; noise is the filter's. Both are generated from a fixed seed, so every environment gets the same pixels (ADR 0011)."},
  {"id": "hist-atomic-hist-local", "term": "hist-atomic, hist-local", "page": "workloads", "def": "The two ways the histogram is built: shared counters that every thread adds to, or per-task counters merged at the end.", "more": "hist-atomic uses padded atomic counters; hist-local uses privatization with fold and reduce. Their time ratio is the RQ2 metric (ADRs 0013, 0014)."},
  {"id": "hist-atomic-private-hist-atomic-packed", "term": "hist-atomic-private, hist-atomic-packed", "page": "extras", "def": "Two extra histogram variants: one padded table per thread with no sharing, and shared counters squeezed into the same cache lines.", "more": "Private separates the cost of the atomic instruction from the cost of sharing: it still costs Chrome 1.85 times native at k = 1 with nothing shared. Packed shows what false sharing does (ADR 0052)."},
  {"id": "checksum", "term": "Checksum", "page": "workloads", "def": "A number computed from a workload's whole output, so two outputs can be compared with one glance.", "more": "It must be the same for every iteration, every N and every environment; a mismatch stops the campaign. It also makes sure the compiler cannot skip the work (ADR 0024)."},
  {"id": "fnv-1a", "term": "FNV-1a", "page": "workloads", "def": "A simple recipe that turns any bytes into one 64-bit number.", "more": "Used for the checksum of the output and the fingerprint of the input; cheap enough to run after every iteration."},
  {"id": "input-fingerprint", "term": "Input fingerprint", "page": "workloads", "def": "A checksum of the input pixels, written in every CSV row.", "more": "It proves every environment and every run got exactly the same image (ADR 0027)."},
  {"id": "splitmix64", "term": "SplitMix64", "page": "workloads", "def": "The random number recipe that generates the inputs, always the same from the same seed.", "more": "Seed 0x5EED; the same generator exists in Rust and the inputs are checked by fingerprint (ADR 0011)."},
  {"id": "workload-trait", "term": "Workload (trait)", "page": "code", "def": "The Rust interface every workload implements: a reset that is not timed, the timed work, and a checksum.", "more": "Adding a workload means implementing it and registering a name; the measurement loop and the CSV never change (bench/src/workloads/workload.rs)."},
  {"id": "run-in-pool", "term": "run_in_pool", "page": "trace", "def": "The one function both hosts call to execute a run: the native main and the browser's coordinating worker.", "more": "It checks the pool has the right number of threads, runs calibration, warm-up and the measured iterations, and returns the records that become CSV rows (bench/src/run.rs)."},
  {"id": "phase", "term": "Phase", "page": "protocol", "def": "The CSV column that says what kind of iteration a row is.", "more": "calibration-pause, calibration-warm, calibration-cold, warmup, measured. The analysis reads only the measured rows; the fork-join numbers come from the calibration rows (ADR 0030)."},
  {"id": "calibration-warm-cold", "term": "Calibration (warm, cold)", "page": "protocol", "def": "Timing an empty parallel call at the start of every run, back to back (warm) and after a pause (cold).", "more": "It measures the fork-join cost of the pool on its own, before any workload: about 7.9 µs natively and 110 µs in Chrome at N = 8, warm medians (ADR 0030)."},
  {"id": "start-delay", "term": "Start delay", "page": "protocol", "def": "A pause the page takes before starting, so the browser's own start-up work is over.", "more": "3 s for every browser run; a pilot found the first iterations biased without it (ADR 0048)."},
  {"id": "discarded-first-launch", "term": "Discarded first launch", "page": "campaigns", "def": "One browser start per session whose results are thrown away.", "more": "The first launch on a machine is much slower (nothing is cached yet), so it is run and discarded before the real runs (ADR 0034)."},
  {"id": "campaign", "term": "Campaign", "page": "campaigns", "def": "Every run of one spec, executed end to end in a seeded random order.", "more": "The main campaign is 5310 runs; the tier, counters, SIMD, cutoff, grain, weak scaling, extras and hybrid campaigns are the exploratory ones. Each lives in data/raw/<name>/."},
  {"id": "order-seed", "term": "Order seed", "page": "campaigns", "def": "The number that fixes the random order of a campaign's runs, so the same order can be replayed.", "more": "2026112201 for the main campaign; recorded in campaign.json (ADR 0034)."},
  {"id": "strict-validation", "term": "Strict validation", "page": "campaigns", "def": "A set of checks on every run's context; a run that fails one is excluded.", "more": "Turbo off, governor, SMT off, the CPU mask, the shield, the browser version, no escaped process, no mixed build. A run is never silently kept (ADR 0040)."},
  {"id": "baseline-compiler", "term": "Baseline and optimizing compiler", "page": "rq2", "def": "The two compilers inside a browser engine: a quick one that produces plain machine code at once, and a slower one that produces faster code for the parts that run a lot.", "more": "V8 calls them Liftoff and TurboFan; SpiderMonkey calls them Baseline and Ion. The study's campaigns measure the optimizing one, which the tier campaign confirmed by running each browser with one compiler only (ADR 0089). For an atomic add, V8's baseline compiler emits one lock xadd and its optimizing compiler a read and a compare-and-swap that retries."},
  {"id": "engine-arm", "term": "Engine arm", "page": "rq2", "def": "One way of starting a browser for a campaign: as shipped, with its baseline compiler only, or with its optimizing compiler only.", "more": "An arm is a set of Chrome --js-flags and Firefox preferences listed in a spec. Arms are shuffled into the run order like everything else and every run records its arm. Only the tier campaign uses more than the default arm (harness/campaigns/tier-v3.json)."},
  {"id": "probe", "term": "Probe", "page": "rq2", "def": "A small one-off test made to check one explanation; its numbers are evidence for a reading, never results of the study.", "more": "The atomic increment probe is a native program that counts the same image into the same padded table, built once per way of adding one to a counter (data/probes/atomic-increment). The engine-code probe holds the machine code each engine runs for each kernel (data/probes/engine-code)."},
  {"id": "prediction", "term": "Prediction written first", "page": "explains", "def": "What a test should show if an explanation is right and if it is wrong, written down before the test runs.", "more": "Without it any outcome can be read as support. ADR 0088 lists nine questions with both columns filled in before the tests ran; one prediction failed in part and one hypothesis was not supported, and both are kept as such."},
  {"id": "sequential-reference", "term": "Sequential reference", "page": "explains", "def": "The same work done by plain code with no thread pool at all, to check that the one-thread baseline of a speedup is not slow.", "more": "The workloads filter-seq and hist-seq of measured/v3 call the same kernels from a plain loop. The pool of one thread costs between -7% and +5% against them, so the relative speedup is not inflated by its baseline (campaign-v3-sequential.csv)."},
  {"id": "gate", "term": "Gate", "page": "session", "def": "A short rehearsal before a long campaign that must pass a few fixed checks, so that a gross problem is found in minutes and not after a night.", "more": "The gate of measured/v3 is 135 runs at the real size, checked for equal outputs, samples long enough for the clock, and first iterations within 5% of the last. It failed on one cell twice; ADR 0087 records why the campaign went ahead."},
  {"id": "digest", "term": "Digest (SHA-256)", "page": "session", "def": "A short fingerprint computed from a file's bytes: two files with the same digest are, for every practical purpose, the same file.", "more": "The measured build is compiled twice from scratch and tagged only if the digests of the native runner, the WASM module and the JavaScript glue agree (data/sessions/v3/build/digests.txt). Every campaign records the digests of the files it ran."},
  {"id": "replication", "term": "Replication", "page": "session", "def": "Measuring the same thing again from the start, to see whether the result comes back.", "more": "measured/v3 repeats every campaign of measured/v2 on a corrected build. The ten primary contrasts are decided the same way on both. Because the v2 results were known, the rules for v3 were fixed before any v3 run existed (ADR 0084)."},
  {"id": "adr", "term": "ADR", "page": "decisions", "def": "A short file that records one design decision: what the situation was, what was decided, and what follows from it.", "more": "Architecture Decision Record. One Markdown file per decision in docs/adr/, numbered; a later ADR amends an earlier one, never rewrites it (ADR 0010)."},
  {"id": "pull-request", "term": "Pull request", "page": "workflow", "def": "A proposed change on a branch that the checks and a reviewer look at before it is merged.", "more": "Filled from .github/pull_request_template.md; small, one at a time, merged when CI is green and the review has been read."},
  {"id": "ci", "term": "CI", "page": "workflow", "def": "The checks GitHub runs on every push to a pull request.", "more": "Continuous integration. Five jobs: changes, rust, browser, tables, python; make test runs most of them locally (.github/workflows/ci.yml)."},
  {"id": "squash-merge", "term": "Squash merge", "page": "workflow", "def": "Merging a pull request as one single commit on main.", "more": "The branch's many small commits become one line in the history, titled after the PR, so main reads as a list of finished changes."}
];
